250	    /**
251	     * Loads the owner with the given id and, when it exists, produces the response through
252	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
253	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
254	     * the not-found response are written in exactly one place rather than copied into each method.
255	     *
256	     * @param ownerId the id of the owner to load
257	     * @param action builds the response for an existing owner
258	     * @param <T> the response body type
259	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
260	     */
261	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
262	        Owner owner = this.clinicService.findOwnerById(ownerId);
263	        if (owner == null) {
264	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	        }
266	        return action.apply(owner);
267	    }
268	
269	    /**
270	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
271	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
272	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
273	     * return their owner through this method, so an owner is decorated identically on either path
274	     * and each derived field is computed in exactly one place.
275	     *
276	     * @param owner the persisted owner to represent
277	     * @return the owner DTO with its derived read-only fields populated
278	     */
279	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
280	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
281	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
282	        ownerDto.setIdentityKey(identityKey(owner));
283	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
284	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
285	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
286	        return ownerDto;
287	    }
288	
289	    /**
290	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
291	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
292	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
293	     * blank (e.g. {@code "   "}). The offending field names are reported through an
294	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
295	     * as a 400 response carrying an {@code errors} array of field names.
296	     *
297	     * @param ownerFieldsDto the submitted owner fields
298	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
299	     */
300	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
301	        List<String> blankFields = new ArrayList<>();
302	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
303	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
304	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
305	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
306	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
307	        if (!blankFields.isEmpty()) {
308	            throw new InvalidOwnerFieldsException(blankFields);
309	        }
310	    }
311	
312	    private void addIfBlank(List<String> blankFields, String field, String value) {
313	        if (value != null && value.isBlank()) {
314	            blankFields.add(field);
315	        }
316	    }
317	
318	    /**
319	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
320	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
321	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
322	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
323	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
324	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
325	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
326	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
327	     *
328	     * @param city the city of the owner being created
329	     * @param postcode the supplied postcode, or {@code null} when omitted
330	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
331	     */
332	    private void rejectInvalidPostcode(String city, String postcode) {
333	        if (postcode == null || postcode.isBlank()) {
334	            return;
335	        }
336	        Region.forCity(city).ifPresent(region -> {
337	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
338	                throw new InvalidOwnerPostcodeException(postcode, city);
339	            }
340	        });
341	    }
342	
343	    /**
344	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
345	     * the {@code customerCode}.
346	     */
347	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
348	
349	    /**
350	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
351	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
352	     * its {@code postcode} (falling back to its {@code city}) through the shared
353	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
354	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
355	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
356	     * function of the owner's region and telephone-plus-name identity.
357	     *
358	     * @param owner the owner being created, with its telephone already normalized
359	     * @return the formatted customer code
360	     */
361	    private String customerCode(Owner owner) {
362	        String region = Region.code(owner.getPostcode(), owner.getCity());
363	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
364	        return region + "-" + hash8;
365	    }
366	
367	    /**
368	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
369	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
370	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
371	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
372	     * new owner and surfaced as the read-only {@code namesakeCount} field.
373	     *
374	     * @param firstName the first name of the owner being created
375	     * @param lastName the last name of the owner being created
376	     * @return the number of existing owners with the same first and last name (case-insensitive)
377	     */
378	    private int namesakeCount(String firstName, String lastName) {
379	        return (int) this.clinicService.findAllOwners().stream()
380	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
381	                && equalsIgnoreCase(owner.getLastName(), lastName))
382	            .count();
383	    }
384	
385	    private boolean equalsIgnoreCase(String a, String b) {
386	        return a == null ? b == null : a.equalsIgnoreCase(b);
387	    }
388	
389	    /**
390	     * The maximum number of owners a single city may contain. Once a city already holds this many
391	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
392	     */
393	    private static final long MAX_OWNERS_PER_CITY = 50L;
394	
395	    /**
396	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
397	     * owners. Existing owners are matched to the requested city case-insensitively (using
398	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
399	     * the per-city counting used for the customer code. A city at capacity is reported through an
400	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
401	     * 409 Conflict response.
402	     *
403	     * @param city the city of the owner being created
404	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
405	     */
406	    private void rejectCityAtCapacity(String city) {
407	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
408	            throw new OwnerCityAtCapacityException(city);
409	        }
410	    }
411	
412	    /**
413	     * Counts the existing owners whose {@code city} matches the given city, compared
414	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
415	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
416	     *
417	     * @param city the city to count owners for
418	     * @return the number of existing owners in that city
419	     */
420	    private long ownersInCity(String city) {
421	        return this.clinicService.findAllOwners().stream()
422	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
423	            .count();
424	    }
425	
426	    /**
427	     * The maximum number of owners that may be registered on a single day. Once this many owners
428	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
429	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
430	     */
431	    private static final long MAX_OWNERS_PER_DAY = 100L;
432	
433	    /**
434	     * Resolves the effective registration date for a create request: the value supplied in the
435	     * request when present, otherwise the server's current date. The result is the raw effective
436	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
437	     *
438	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
439	     * @return the supplied date, or today when none was supplied
440	     */
441	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
442	        return suppliedDate != null ? suppliedDate : LocalDate.now();
443	    }
444	
445	    /**
446	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
447	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
448	     * today when omitted - but it may never be in the future. The check is applied to the raw
449	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
450	     * future date is rejected regardless of how that adjustment would move it. A future date is
451	     * reported through a {@link FutureRegistrationDateException}, which the
452	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
453	     * {@code registrationDate} field.
454	     *
455	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
456	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
457	     */
458	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
459	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
460	            throw new FutureRegistrationDateException(suppliedDate);
461	        }
462	    }
463	
464	    /**
465	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
466	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
467	     * the effective registration date so that a weekend value - whether supplied in the request or
468	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
469	     * registration date (such as the membership number's year segment and the daily create-limit
470	     * bucket) uses the adjusted business day.
471	     *
472	     * @param date the effective registration date
473	     * @return the same date when it is a weekday, otherwise the next Monday
474	     */
475	    private LocalDate businessDay(LocalDate date) {
476	        DayOfWeek dayOfWeek = date.getDayOfWeek();
477	        if (dayOfWeek == DayOfWeek.SATURDAY) {
478	            return date.plusDays(2);
479	        }
480	        if (dayOfWeek == DayOfWeek.SUNDAY) {
481	            return date.plusDays(1);
482	        }
483	        return date;
484	    }
485	
486	    /**
487	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
488	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
489	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
490	     * renders as a 429 Too Many Requests response.
491	     *
492	     * @param date the registration date of the owner being created (today)
493	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
494	     */
495	    private void rejectDailyRegistrationLimit(LocalDate date) {
496	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
497	            throw new DailyOwnerRegistrationLimitException(date);
498	        }
499	    }
500	
501	    /**
502	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
503	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
504	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
505	     * day's owners identically.
506	     *
507	     * @param date the registration date to count owners for
508	     * @return the number of existing owners registered on that day
509	     */
510	    private long ownersRegisteredOn(LocalDate date) {
511	        return this.clinicService.findAllOwners().stream()
512	            .filter(owner -> date.equals(owner.getRegistrationDate()))
513	            .count();
514	    }
515	
516	    /**
517	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
518	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
519	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
520	     */
521	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
522	
523	    /**
524	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
525	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
526	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
527	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
528	     * without a registration date, such as seed data) is never flagged.
529	     *
530	     * @param date the owner's registration date (the day it was created), or {@code null}
531	     * @return {@code true} if the day already holds more than the warning threshold of owners
532	     */
533	    private boolean bulkSignupWarning(LocalDate date) {
534	        if (date == null) {
535	            return false;
536	        }
537	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
538	    }
539	
540	    /**
541	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
542	     * The identity key consolidates the former separate telephone, email and household duplicate
543	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
544	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
545	     * key, two members of the same household (same {@code householdId}) with different telephones have
546	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
547	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
548	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
549	     *
550	     * @param owner the fully-populated owner being created (telephone, email and household id set)
551	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
552	     */
553	    private void rejectDuplicateIdentity(Owner owner) {
554	        String key = identityKey(owner);
555	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
556	        if (duplicate) {
557	            throw new DuplicateOwnerIdentityException(key);
558	        }
559	    }
560	
561	    /**
562	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
563	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
564	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
565	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
566	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
567	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
568	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
569	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
570	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
571	     *
572	     * @param owner the fully-populated owner being created (telephone normalized)
573	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
574	     */
575	    private Integer possibleDuplicateOf(Owner owner) {
576	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
577	            return null;
578	        }
579	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
580	        return this.clinicService.findAllOwners().stream()
581	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
582	                && owner.getPostcode().equals(existing.getPostcode())
583	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
584	            .map(Owner::getId)
585	            .filter(java.util.Objects::nonNull)
586	            .findFirst()
587	            .orElse(null);
588	    }
589	
590	    /**
591	     * Reduces an owner to its derived {@code identityKey}, formatted
592	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
593	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
594	     * normalized (lower-cased) email or the empty string when absent (see
595	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
596	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
597	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
598	     * single duplicate check compares this one value across owners.
599	     *
600	     * @param owner the owner to derive the identity key for
601	     * @return the owner's identity key
602	     */
603	    private String identityKey(Owner owner) {
604	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
605	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
606	        String email = normalizedEmail == null ? "" : normalizedEmail;
607	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
608	        return telephone + "|" + email + "|" + household;
609	    }
610	
611	    /**
612	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
613	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
614	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
615	     * checks reduce both an existing owner and the owner being created to the same canonical key;
616	     * this returns the matched existing owner itself, so a caller can either reject the collision or
617	     * record which owner was matched.
618	     *
619	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
620	     * @param key the canonical key of the owner being created
621	     * @return the first existing owner sharing the key, or empty when none does
622	     */
623	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
624	        return this.clinicService.findAllOwners().stream()
625	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
626	            .findFirst();
627	    }
628	
629	    /**
630	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
631	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
632	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
633	     * being created to the same canonical key and reject a match.
634	     *
635	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
636	     * @param key the canonical key of the owner being created
637	     * @return {@code true} if some existing owner shares the key
638	     */
639	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
640	        return findExistingOwner(keyExtractor, key).isPresent();
641	    }
642	
643	    /**
644	     * Delimiter joining the canonical household fields when deriving the shared {@code householdId}.
645	     * A run of whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so
646	     * this newline can never occur inside a canonical value and the two fields cannot bleed into one
647	     * another across the join.
648	     */
649	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
650	
651	    /**
652	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
653	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
654	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
655	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
656	     *
657	     * @param value the raw field value, or {@code null}
658	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
659	     */
660	    private String canonicalizeHousehold(String value) {
661	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
662	    }
663	
664	    /**
665	     * Derives the stable, shared {@code householdId} for an owner joining a household via
666	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
667	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
668	     * owner with the same last name at the same address - regardless of casing or spacing - is
669	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
670	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
671	     *
672	     * @param owner the owner being created
673	     * @return the shared household identifier
674	     */
675	    private String householdId(Owner owner) {
676	        String key = canonicalizeHousehold(owner.getLastName())
677	            + HOUSEHOLD_KEY_DELIMITER + canonicalizeHousehold(owner.getAddress());
678	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
679	    }
680	
681	    /**
682	     * Number of leading hex characters of the household hash retained as the shared
683	     * {@code householdId}.
684	     */
685	    private static final int HOUSEHOLD_ID_LENGTH = 16;
686	
687	    /**
688	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
689	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
690	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
691	     * so every such identifier is produced by the same algorithm and differs only in the value it
692	     * hashes and the number of hex characters it keeps.
693	     *
694	     * @param input the value to hash
695	     * @param length the number of leading hex characters to keep
696	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
697	     */
698	    private String hashPrefix(String input, int length) {
699	        try {
700	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
701	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
702	            StringBuilder sb = new StringBuilder(digest.length * 2);
703	            for (byte b : digest) {
704	                sb.append(String.format("%02X", b));
705	            }
706	            return sb.substring(0, length);
707	        } catch (java.security.NoSuchAlgorithmException e) {
708	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
709	        }
710	    }
711	}
