25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
30	    @Mapping(target = "bulkSignupWarning", ignore = true)
31	    @Mapping(target = "identityKey", ignore = true)
32	    @Mapping(target = "possibleDuplicate", ignore = true)
33	    @Mapping(target = "possibleDuplicateOf", ignore = true)
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derives the owner's {@code contactPreference} from the owner's own fields:
38	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
39	     *
40	     * @param owner the owner being mapped
41	     * @return the derived contact preference
42	     */
43	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
44	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
45	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
46	    }
47	
48	    /**
49	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
50	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
51	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
52	     * case the field is absent from the response. The age in whole years is the number of complete
53	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
54	     * registration date is somehow absent the current date is used as the reference.
55	     *
56	     * @param owner the owner being mapped
57	     * @return the derived age band, or {@code null} when no birth date is present
58	     */
59	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
60	        java.time.LocalDate birthDate = owner.getBirthDate();
61	        if (birthDate == null) {
62	            return null;
63	        }
64	        java.time.LocalDate reference = owner.getRegistrationDate() != null
65	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
66	        int age = java.time.Period.between(birthDate, reference).getYears();
67	        if (age < 18) {
68	            return OwnerDto.AgeBandEnum.MINOR;
69	        }
70	        if (age < 65) {
71	            return OwnerDto.AgeBandEnum.ADULT;
72	        }
73	        return OwnerDto.AgeBandEnum.SENIOR;
74	    }
75	
76	    /**
77	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
78	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
79	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
80	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
81	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
82	     * identity keeps the locality consistent with the code an owner is issued.
83	     *
84	     * @param owner the owner being mapped
85	     * @return the derived locality
86	     */
87	    default String locality(Owner owner) {
88	        String code = owner.getCustomerCode();
89	        if (code == null) {
90	            return Region.code(owner.getPostcode(), owner.getCity());
91	        }
92	        int dash = code.indexOf('-');
93	        return dash >= 0 ? code.substring(0, dash) : code;
94	    }
95	
96	    /**
97	     * Derives the owner's numeric {@code membershipLevel} from the owner's own fields. Starts at
98	     * {@code 1}, adds {@code 1} when an email is present, adds {@code 1} when the owner's
99	     * {@code namesakeCount} is {@code 0}, and is capped at {@code 3} (level {@code 4} is reserved
100	     * for tenure).
101	     *
102	     * @param owner the owner being mapped
103	     * @return the derived membership level, between {@code 1} and {@code 3}
104	     */
105	    default Integer membershipLevel(Owner owner) {
106	        int level = 1;
107	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
108	        if (hasEmail) {
109	            level++;
110	        }
111	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
112	        if (uniqueName) {
113	            level++;
114	        }
115	        return Math.min(level, 3);
116	    }
117	
118	    /**
119	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
120	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
121	     * {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the customer code or the
122	     * registration date is absent.
123	     *
124	     * @param owner the owner being mapped
125	     * @return the formatted membership number, or {@code null} when it cannot be derived
126	     */
127	    default String membershipNumber(Owner owner) {
128	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
129	            return null;
130	        }
131	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
132	    }
133	
134	    /**
135	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
136	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
137	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
138	     * the customer code is absent.
139	     *
140	     * @param owner the owner being mapped
141	     * @return the Luhn check digit, or {@code null} when no customer code is present
142	     */
143	    default Integer checkDigit(Owner owner) {
144	        String code = owner.getCustomerCode();
145	        if (code == null) {
146	            return null;
147	        }
